import type { ColorTokens } from "@/registry/types/pdf-themes";

/** Theme color token keys that can be used for the color prop */
export const THEME_COLOR_KEYS = [
  "foreground",
  "background",
  "muted",
  "mutedForeground",
  "primary",
  "primaryForeground",
  "border",
  "accent",
  "destructive",
  "success",
  "warning",
  "info",
] as const satisfies (keyof ColorTokens)[];

/** Resolves a color value: theme token key → hex, or raw CSS color as-is. */
export const resolveColor = (value: string, colors: ColorTokens): string => {
  const key = value as (typeof THEME_COLOR_KEYS)[number];
  return THEME_COLOR_KEYS.includes(key) ? colors[key] : value;
};

import type { ReactNode } from "react";

import { Fixed, View } from "@/registry/bases/forme/lib/pdf-primitives";
import type { Style } from "@/registry/bases/forme/lib/pdf-primitives";

export const MaybeFixed = ({
  fixed,
  position,
  wrap,
  style,
  children,
}: {
  fixed?: boolean;
  position: "header" | "footer";
  wrap?: boolean;
  style?: Style | Style[];
  children?: ReactNode;
}) => {
  const view = (
    <View wrap={wrap} style={style as never}>
      {children}
    </View>
  );
  if (!fixed) {
    return view;
  }
  return <Fixed position={position}>{view}</Fixed>;
};

import type { Style } from "@formepdf/react";
import { isValidElement } from "react";
import type { DependencyList, ReactNode } from "react";

import { professionalTheme } from "@/registry/themes/professional";

export type PdfcnTheme = typeof professionalTheme;

let serializedTheme = professionalTheme;

export interface PdfcnThemeProviderProps {
  theme?: PdfcnTheme;
  children: ReactNode;
}

type PdfStyleInput = Style | PdfStyleInput[] | false | null | undefined;

const mergeStyleInput = (target: Style, input: PdfStyleInput): void => {
  if (Array.isArray(input)) {
    for (const item of input) {
      mergeStyleInput(target, item);
    }
  } else if (input) {
    Object.assign(target, input);
  }
};

export const mergePdfStyles = (...inputs: PdfStyleInput[]): Style => {
  const merged: Style = {};
  for (const input of inputs) {
    mergeStyleInput(merged, input);
  }
  return merged;
};

const renderForSerializer = (
  children: ReactNode,
  theme: PdfcnTheme
): ReactNode => {
  serializedTheme = theme;

  if (!isValidElement(children) || typeof children.type !== "function") {
    return children;
  }
  if ((children.type as { __formeType?: string }).__formeType === "Document") {
    return children;
  }

  return (children.type as (props: unknown) => ReactNode)(children.props);
};

export const PdfcnThemeProvider = ({
  theme,
  children,
}: PdfcnThemeProviderProps) =>
  renderForSerializer(children, theme ?? professionalTheme);

export const usePdfcnTheme = (): PdfcnTheme => serializedTheme;

export const useSafeMemo = <T,>(factory: () => T, _deps: DependencyList): T =>
  factory();

import {
  Fixed as FormeFixed,
  Image as FormeImage,
  Link as FormeLink,
  StyleSheet,
  Text as FormeText,
  View as FormeView,
} from "@formepdf/react";
import type {
  FixedProps,
  ImageProps,
  LinkProps,
  Style,
  TextProps,
  ViewProps,
} from "@formepdf/react";

export type FormeStyleInput =
  | Style
  | false
  | null
  | undefined
  | readonly FormeStyleInput[];

export const mergeFormeStyles = (input: FormeStyleInput): Style | undefined => {
  if (!input) {
    return undefined;
  }

  if (!Array.isArray(input)) {
    return input as Style;
  }

  const merged: Style = {};
  for (const entry of input) {
    const resolved = mergeFormeStyles(entry);
    if (resolved) {
      Object.assign(merged, resolved);
    }
  }

  return Object.keys(merged).length > 0 ? merged : undefined;
};

type WithStyle<T> = Omit<T, "style"> & { style?: FormeStyleInput };

export const View = ({ style, ...props }: WithStyle<ViewProps>) => (
  <FormeView {...props} style={mergeFormeStyles(style)} />
);

export const Text = ({ style, ...props }: WithStyle<TextProps>) => (
  <FormeText {...props} style={mergeFormeStyles(style)} />
);

export const Link = ({ style, ...props }: WithStyle<LinkProps>) => (
  <FormeLink {...props} style={mergeFormeStyles(style)} />
);

export const Image = ({ style, ...props }: WithStyle<ImageProps>) => (
  <FormeImage {...props} style={mergeFormeStyles(style)} />
);

export const Fixed = ({ style, ...props }: WithStyle<FixedProps>) => (
  <FormeFixed {...props} style={mergeFormeStyles(style)} />
);

export { StyleSheet };
export type { Style };

import { Svg as FormeSvg } from "@formepdf/react";
import {
  Children,
  Fragment,
  cloneElement,
  createElement,
  isValidElement,
} from "react";
import type { ReactNode, CSSProperties } from "react";

type AnyProps = Record<string, unknown> & {
  children?: ReactNode;
  style?: CSSProperties;
};

const SVG_ATTRIBUTE_NAMES: Record<string, string> = {
  className: "class",
  dominantBaseline: "dominant-baseline",
  fillOpacity: "fill-opacity",
  fontFamily: "font-family",
  fontSize: "font-size",
  fontStyle: "font-style",
  fontWeight: "font-weight",
  strokeDasharray: "stroke-dasharray",
  strokeLinecap: "stroke-linecap",
  strokeLinejoin: "stroke-linejoin",
  strokeOpacity: "stroke-opacity",
  strokeWidth: "stroke-width",
  textAnchor: "text-anchor",
};

const normalizeSvgProps = (props: AnyProps): AnyProps => {
  const normalized: AnyProps = {};

  for (const [name, value] of Object.entries(props)) {
    if (value === undefined) {
      continue;
    }

    if (name === "style" && value && typeof value === "object") {
      for (const [styleName, styleValue] of Object.entries(value)) {
        normalized[SVG_ATTRIBUTE_NAMES[styleName] ?? styleName] = styleValue;
      }
      continue;
    }

    normalized[SVG_ATTRIBUTE_NAMES[name] ?? name] = value;
  }

  return normalized;
};

const resolveSvgChildren = (children: ReactNode): ReactNode =>
  Children.map(children, (child) => {
    if (!isValidElement<AnyProps>(child)) {
      return child;
    }

    if (typeof child.type === "function") {
      const resolved = (child.type as (props: AnyProps) => ReactNode)(
        child.props
      );
      return resolveSvgChildren(resolved);
    }

    if ((child.type as unknown) === Fragment) {
      return resolveSvgChildren(child.props.children);
    }

    if (child.props.children === undefined) {
      return child;
    }

    return cloneElement(
      child,
      undefined,
      resolveSvgChildren(child.props.children)
    );
  });

export const Svg = ({
  children,
  width,
  height,
  viewBox,
  style,
  ...rest
}: AnyProps & { width?: number; height?: number; viewBox?: string }) => (
  <FormeSvg
    width={width as number}
    height={height as number}
    viewBox={viewBox as string | undefined}
    style={style as never}
    {...rest}
  >
    {resolveSvgChildren(children)}
  </FormeSvg>
);

export const Circle = (props: AnyProps) =>
  createElement("circle", normalizeSvgProps(props));
export const Rect = (props: AnyProps) =>
  createElement("rect", normalizeSvgProps(props));
export const G = (props: AnyProps) =>
  createElement("g", normalizeSvgProps(props));
export const Line = (props: AnyProps) =>
  createElement("line", normalizeSvgProps(props));
export const Path = (props: AnyProps) =>
  createElement("path", normalizeSvgProps(props));
export const SvgText = (props: AnyProps) =>
  createElement(
    "text",
    normalizeSvgProps({ fontFamily: "sans-serif", ...props })
  );
